def _generate_expression(self):
    # Validate that braces are properly matched before processing
    depth = 0
    i = 0
    fmt = self._format
    while i < len(fmt):
        if fmt[i:i+2] == '{{':
            i += 2
        elif fmt[i:i+2] == '}}':
            i += 2
        elif fmt[i] == '{':
            depth += 1
            i += 1
        elif fmt[i] == '}':
            if depth > 0:
                depth -= 1
            else:
                raise ValueError('single } in format')
            i += 1
        else:
            i += 1
    if depth != 0:
        raise ValueError('single { in format string')

